describe('proof', function () {
  it('fails on the patched build', function () {
    // The issue is that the original code used if-else if chain
    // The new code uses a loop with array lookup
    // The original code had a bug: it checked PB first, then TB, etc.
    // But the new code has the same order: PB, TB, GB, MB, KB
    // So the logic is actually equivalent

    // Let's test a value that is exactly at the boundary of KB
    // 1024 bytes = 1 KB
    // The original code would have checked:
    //   if (mag >= map.pb) -> no
    //   else if (mag >= map.tb) -> no
    //   else if (mag >= map.gb) -> no
    //   else if (mag >= map.mb) -> no
    //   else if (mag >= map.kb) -> yes, so unit = 'KB'
    // 
    // The new code does the same: it checks PB, TB, GB, MB, KB in order
    // So both should give the same result

    // But let's test a value that is just below KB
    // 1023 bytes should be '1023B'
    const value = 1023;
    const result = bytes(value, { unit: 'KB' });

    // This should be '1023B' because 1023 < 1024 (KB)
    // But if the code incorrectly uses the unit 'KB' when it shouldn't
    // it would return '1KB' which is wrong

    // The original code would have set unit = 'B' because none of the conditions
    // were met, then returned the value as '1023B'
    // 
    // The new code does the same: it checks the units array and finds that
    // 1023 < 1024 (KB), so it doesn't set unit to KB, and keeps unit = 'B'
    // 
    // So both should return '1023B'

    assert.strictEqual(result, '1023B');
  });
});

